package bot

import (
	"context"
	"log/slog"
	"time"

	applog "bakery/pkg/logger"

	tele "gopkg.in/telebot.v3"
)

const requestContextKey = "request_context"

// register wires the only two updates the bot handles: /start (begin the
// password gate) and free text (the password itself). Everything else lives in
// the mini app now.
func (b *OrderBot) register() {
	bt := b.tele
	bt.Use(b.privateChatOnly, b.logMiddleware)

	bt.Handle("/start", b.handleStart)
	bt.Handle(tele.OnText, b.handleText)
}

func (b *baseBot) logMiddleware(next tele.HandlerFunc) tele.HandlerFunc {
	return func(c tele.Context) error {
		start := time.Now()
		ctx := context.Background()
		if sender := c.Sender(); sender != nil {
			ctx = applog.WithTelegramUser(ctx, sender.ID, sender.Username)
		}

		if cb := c.Callback(); cb != nil {
			ctx = applog.WithPayload(ctx, applog.CallbackPayload(cb.Unique, cb.Data))
		} else if c.Message() != nil {
			ctx = applog.WithPayload(ctx, applog.MessagePayload(c.Text()))
		} else {
			ctx = applog.WithPayload(ctx, applog.UpdatePayload())
		}
		c.Set(requestContextKey, ctx)

		err := next(c)

		if err != nil {
			slog.ErrorContext(ctx, "telegram update failed",
				"error", err,
				"duration", time.Since(start).Round(time.Millisecond).String(),
			)
			return err
		}

		slog.InfoContext(ctx, "telegram update",
			"status", "ok",
			"duration", time.Since(start).Round(time.Millisecond).String(),
		)
		return err
	}
}

func requestContext(c tele.Context) context.Context {
	if raw := c.Get(requestContextKey); raw != nil {
		if ctx, ok := raw.(context.Context); ok {
			return ctx
		}
	}
	return context.Background()
}

package bot

import (
	"context"

	accessdomain "bakery/internal/services/auth/domain"
	departmentuc "bakery/internal/services/department/usecase/department"
)

// The bot depends on these narrow, bot-owned backend ports rather than on the
// services' full use-case interfaces (interface segregation + dependency
// inversion). The bot is now a thin auth gate (password check via /start) plus
// the order-event notifier to the workshop; it needs only auth and department
// lookups.

// AuthBackend is the slice of the auth service the bot uses.
type AuthBackend interface {
	VerifyPassword(ctx context.Context, username, password string) (accessdomain.AuthUser, error)
	AuthenticateTelegram(ctx context.Context, telegramID int64, telegramUsername string) (accessdomain.AuthUser, error)
	GetUserByTelegramID(ctx context.Context, telegramID int64) (accessdomain.AuthUser, error)
	GetUserByTelegramUsername(ctx context.Context, telegramUsername string) (accessdomain.AuthUser, error)
	ListUsersByRole(ctx context.Context, role string) ([]accessdomain.AuthUser, error)
}

// DepartmentBackend is the slice of the department service the bot uses (for
// rendering order notifications).
type DepartmentBackend interface {
	GetByID(ctx context.Context, id int64) (departmentuc.Department, error)
}

package bot

import (
	"fmt"
	"net/url"
	"strings"
	"sync"
	"time"

	"bakery/pkg/rabbitmq/consumer"

	tele "gopkg.in/telebot.v3"
)

type baseBot struct {
	tele           *tele.Bot
	authSvc        AuthBackend
	departmentSvc  DepartmentBackend
	eventConsumer  *consumer.Consumer
	miniAppURL     string
	workshopChatID int64
}

type OrderBot struct {
	*baseBot
	mu       sync.Mutex
	sessions map[int64]*session
}

func NewOrderBot(
	token string,
	authSvc AuthBackend,
	departmentSvc DepartmentBackend,
	eventConsumer *consumer.Consumer,
	miniAppURL string,
	workshopChatID int64,
) (*OrderBot, error) {
	miniAppURL = strings.TrimSpace(miniAppURL)
	if miniAppURL != "" {
		parsed, err := url.Parse(miniAppURL)
		if err != nil || parsed.Scheme != "https" || parsed.Host == "" {
			return nil, fmt.Errorf("orderbot: mini app URL must be a valid https URL")
		}
	}

	b, err := newTelegramBot(token)
	if err != nil {
		return nil, fmt.Errorf("orderbot: new: %w", err)
	}

	bot := &OrderBot{
		baseBot: &baseBot{
			tele:           b,
			authSvc:        authSvc,
			departmentSvc:  departmentSvc,
			eventConsumer:  eventConsumer,
			miniAppURL:     miniAppURL,
			workshopChatID: workshopChatID,
		},
		sessions: make(map[int64]*session),
	}
	bot.register()
	return bot, nil
}

func newTelegramBot(token string) (*tele.Bot, error) {
	return tele.NewBot(tele.Settings{
		Token:  token,
		Poller: &tele.LongPoller{Timeout: 10 * time.Second},
	})
}

func (b *OrderBot) Start() {
	go b.cleanupLoop()
	b.tele.Start()
}

func (b *OrderBot) Name() string {
	if b == nil || b.tele == nil || b.tele.Me == nil {
		return ""
	}
	return b.tele.Me.FirstName
}

func (b *OrderBot) Username() string {
	if b == nil || b.tele == nil || b.tele.Me == nil {
		return ""
	}
	return b.tele.Me.Username
}

func (b *OrderBot) Stop() {
	b.tele.Stop()
}

package monitoruc

import (
	"context"
	"fmt"
	"sort"
	"strings"

	monitoringdomain "bakery/internal/services/monitor/domain"
	orderdomain "bakery/internal/services/order/domain"
)

type Service struct {
	repo   Repository
	domain *monitoringdomain.Service
}

var _ UseCase = (*Service)(nil)

func NewService(repo Repository) *Service {
	return &Service{repo: repo, domain: monitoringdomain.NewService()}
}

func (s *Service) GetIngredientsByCode(ctx context.Context, code string, order orderdomain.Order) (monitoringdomain.IngredientReport, error) {
	ingredient, err := s.repo.ResolveIngredient(ctx, strings.TrimSpace(code))
	if err != nil {
		return monitoringdomain.IngredientReport{}, err
	}
	orderGraph, err := s.repo.LoadOrderGraph(ctx, order)
	if err != nil {
		return monitoringdomain.IngredientReport{}, err
	}
	return s.calculateIngredientReport(ingredient, orderGraph)
}

func (s *Service) GetBatchIngredientsByCodes(ctx context.Context, codes []string, orders []orderdomain.Order) (monitoringdomain.BatchMonitoringReport, error) {
	result := monitoringdomain.BatchMonitoringReport{
		Orders:       make([]monitoringdomain.OrderMonitoringReport, 0, len(orders)),
		TotalReports: make([]monitoringdomain.IngredientReport, 0, len(codes)),
	}
	if len(codes) == 0 || len(orders) == 0 {
		return result, nil
	}

	ingredients := make([]Ingredient, 0, len(codes))
	for _, code := range codes {
		ingredient, err := s.repo.ResolveIngredient(ctx, strings.TrimSpace(code))
		if err != nil {
			return result, err
		}
		ingredients = append(ingredients, ingredient)
	}

	totalByCode := make(map[string]monitoringdomain.IngredientReport, len(ingredients))
	breakdownByCode := make(map[string]map[string]monitoringdomain.IngredientDishBreakdown, len(ingredients))
	componentsByCode := make(map[string]*componentAccumulator, len(ingredients))

	for _, order := range orders {
		orderGraph, err := s.repo.LoadOrderGraph(ctx, order)
		if err != nil {
			return result, err
		}
		orderReport := monitoringdomain.OrderMonitoringReport{
			OrderNumber: order.Number,
			Reports:     make([]monitoringdomain.IngredientReport, 0, len(ingredients)),
		}
		for _, ingredient := range ingredients {
			report, err := s.calculateIngredientReport(ingredient, orderGraph)
			if err != nil {
				return result, err
			}
			orderReport.Reports = append(orderReport.Reports, report)

			total := totalByCode[ingredient.Code]
			if total.Ingredient.ProductCode == "" {
				total.Ingredient = report.Ingredient
				total.Ingredient.Quantity = 0
			}
			total.Ingredient.Quantity += report.Ingredient.Quantity
			totalByCode[ingredient.Code] = total

			if _, ok := breakdownByCode[ingredient.Code]; !ok {
				breakdownByCode[ingredient.Code] = make(map[string]monitoringdomain.IngredientDishBreakdown)
			}
			for _, breakdown := range report.Breakdown {
				key := breakdown.OrderItemCode + "\x00" + breakdown.OrderItemName
				existing := breakdownByCode[ingredient.Code][key]
				if existing.OrderItemCode == "" {
					existing = monitoringdomain.IngredientDishBreakdown{
						OrderItemCode: breakdown.OrderItemCode,
						OrderItemName: breakdown.OrderItemName,
					}
				}
				existing.OrderItemQuantity += breakdown.OrderItemQuantity
				existing.IngredientQuantity += breakdown.IngredientQuantity
				breakdownByCode[ingredient.Code][key] = existing
			}

			if _, ok := componentsByCode[ingredient.Code]; !ok {
				componentsByCode[ingredient.Code] = newComponentAccumulator()
			}
			componentsByCode[ingredient.Code].add(report.Components)
		}
		result.Orders = append(result.Orders, orderReport)
	}

	for _, ingredient := range ingredients {
		total, ok := totalByCode[ingredient.Code]
		if !ok {
			continue
		}
		for _, breakdown := range breakdownByCode[ingredient.Code] {
			if breakdown.IngredientQuantity > 0 {
				total.Breakdown = append(total.Breakdown, breakdown)
			}
		}
		sort.Slice(total.Breakdown, func(i, j int) bool {
			return total.Breakdown[i].IngredientQuantity > total.Breakdown[j].IngredientQuantity
		})
		if acc := componentsByCode[ingredient.Code]; acc != nil {
			total.Components = acc.components()
		}
		result.TotalReports = append(result.TotalReports, total)
	}

	return result, nil
}

// componentAccumulator суммирует компоненты техкарты по нескольким заказам,
// сохраняя порядок рецепта (порядок первого появления).
type componentAccumulator struct {
	order []string
	byKey map[string]monitoringdomain.IngredientComponent
}

func newComponentAccumulator() *componentAccumulator {
	return &componentAccumulator{byKey: make(map[string]monitoringdomain.IngredientComponent)}
}

func (a *componentAccumulator) add(components []monitoringdomain.IngredientComponent) {
	for _, component := range components {
		key := component.ProductCode + "\x00" + component.ProductName
		existing, ok := a.byKey[key]
		if !ok {
			a.order = append(a.order, key)
			existing = component
			existing.Quantity = 0
		}
		existing.Quantity += component.Quantity
		a.byKey[key] = existing
	}
}

func (a *componentAccumulator) components() []monitoringdomain.IngredientComponent {
	if len(a.order) == 0 {
		return nil
	}
	components := make([]monitoringdomain.IngredientComponent, 0, len(a.order))
	for _, key := range a.order {
		components = append(components, a.byKey[key])
	}
	return components
}

func (s *Service) calculateIngredientReport(ingredient Ingredient, orderGraph OrderGraph) (monitoringdomain.IngredientReport, error) {
	report := monitoringdomain.IngredientReport{
		Ingredient: monitoringdomain.IngredientUsage{
			ProductCode: ingredient.Code,
			ProductName: ingredient.Name,
			Unit:        ingredient.Unit,
		},
	}
	for _, graphItem := range orderGraph.Items {
		breakdown, err := s.calculateOrderItemIngredientUsage(orderGraph.Graph, graphItem, ingredient.ProductID)
		if err != nil {
			return report, err
		}
		if breakdown.IngredientQuantity <= 0 {
			continue
		}
		report.Ingredient.Quantity += breakdown.IngredientQuantity
		report.Breakdown = append(report.Breakdown, breakdown)
	}
	sort.Slice(report.Breakdown, func(i, j int) bool {
		return report.Breakdown[i].IngredientQuantity > report.Breakdown[j].IngredientQuantity
	})
	if report.Ingredient.Quantity > 0 {
		report.Components = s.domain.ComposeRecipe(orderGraph.Graph, ingredient.ProductID, report.Ingredient.Quantity)
	}
	return report, nil
}

func (s *Service) calculateOrderItemIngredientUsage(
	graph monitoringdomain.ProductGraph,
	graphItem OrderGraphItem,
	ingredientID string,
) (monitoringdomain.IngredientDishBreakdown, error) {
	orderItem := graphItem.Item
	// Расчёт идёт по эффективному количеству: факт отработки приоритетнее
	// заявки — тесто считается на то, что реально печётся.
	productionQuantity := orderItem.EffectiveQuantity()
	breakdown := monitoringdomain.IngredientDishBreakdown{
		OrderItemCode:     orderItem.Code,
		OrderItemName:     orderItem.ProductName,
		OrderItemQuantity: productionQuantity,
	}
	used, err := s.domain.CalculateIngredientUsage(graph, graphItem.ProductID, ingredientID, productionQuantity)
	if err != nil {
		return breakdown, fmt.Errorf("calculate ingredient usage for product %s: %w", orderItem.Code, err)
	}
	breakdown.IngredientQuantity = used
	return breakdown, nil
}

package monitoring

import "fmt"

const DefaultMaxDepth = 12

type ProductGraph map[string]ProductRecipe

type ProductRecipe struct {
	Assembly *AssemblyRecipe
	Prepared *PreparedRecipe
}

type AssemblyRecipe struct {
	AssembledAmount float64
	Items           []RecipeItem
}

type PreparedRecipe struct {
	Items []RecipeItem
}

type RecipeItem struct {
	ProductID string
	Amount    float64
	// Code/Name/Unit описывают продукт компонента для отображения состава;
	// на расчёт расхода они не влияют.
	Code string
	Name string
	Unit string
}

type Service struct {
	maxDepth int
}

func NewService() *Service {
	return &Service{maxDepth: DefaultMaxDepth}
}

func (s *Service) CalculateIngredientUsage(graph ProductGraph, productID string, ingredientID string, amount float64) (float64, error) {
	if s == nil {
		s = NewService()
	}
	return s.calculateIngredientUsage(graph, productID, ingredientID, amount, make(map[string]bool, s.maxDepth))
}

// ComposeRecipe раскладывает продукт на компоненты его техкарты (один уровень),
// масштабируя количества на amount. Формулы те же, что и в расчёте расхода:
// сборочная карта — item.Amount * (amount / AssembledAmount),
// карта полуфабриката — item.Amount * amount.
func (s *Service) ComposeRecipe(graph ProductGraph, productID string, amount float64) []IngredientComponent {
	if productID == "" || amount == 0 {
		return nil
	}
	recipe, ok := graph[productID]
	if !ok {
		return nil
	}

	var items []RecipeItem
	scale := amount
	switch {
	case recipe.Assembly != nil:
		if recipe.Assembly.AssembledAmount > 0 {
			scale = amount / recipe.Assembly.AssembledAmount
		}
		items = recipe.Assembly.Items
	case recipe.Prepared != nil:
		items = recipe.Prepared.Items
	default:
		return nil
	}

	components := make([]IngredientComponent, 0, len(items))
	for _, item := range items {
		components = append(components, IngredientComponent{
			ProductCode: item.Code,
			ProductName: item.Name,
			Unit:        item.Unit,
			Quantity:    item.Amount * scale,
		})
	}
	return components
}

func (s *Service) calculateIngredientUsage(
	graph ProductGraph,
	productID string,
	ingredientID string,
	amount float64,
	path map[string]bool,
) (float64, error) {
	if productID == "" || amount == 0 {
		return 0, nil
	}
	if productID == ingredientID {
		return amount, nil
	}
	if path[productID] {
		return 0, nil
	}
	if len(path) >= s.maxDepth {
		return 0, fmt.Errorf("monitor calculation max depth exceeded for product %s", productID)
	}

	path[productID] = true
	defer delete(path, productID)

	recipe, ok := graph[productID]
	if !ok {
		return 0, nil
	}

	if recipe.Assembly != nil {
		return s.calculateAssemblyUsage(graph, *recipe.Assembly, ingredientID, amount, path)
	}
	if recipe.Prepared != nil {
		return s.calculatePreparedUsage(graph, *recipe.Prepared, ingredientID, amount, path)
	}
	return 0, nil
}

func (s *Service) calculateAssemblyUsage(
	graph ProductGraph,
	recipe AssemblyRecipe,
	ingredientID string,
	amount float64,
	path map[string]bool,
) (float64, error) {
	scale := amount
	if recipe.AssembledAmount > 0 {
		scale = amount / recipe.AssembledAmount
	}

	var total float64
	for _, item := range recipe.Items {
		used, err := s.calculateIngredientUsage(graph, item.ProductID, ingredientID, item.Amount*scale, path)
		if err != nil {
			return 0, err
		}
		total += used
	}
	return total, nil
}

func (s *Service) calculatePreparedUsage(
	graph ProductGraph,
	recipe PreparedRecipe,
	ingredientID string,
	amount float64,
	path map[string]bool,
) (float64, error) {
	var total float64
	for _, item := range recipe.Items {
		used, err := s.calculateIngredientUsage(graph, item.ProductID, ingredientID, item.Amount*amount, path)
		if err != nil {
			return 0, err
		}
		total += used
	}
	return total, nil
}

// Package monitorrepo is the persistence adapter of the monitoring service. It
// resolves monitored ingredients and loads recipe graphs from the iiko snapshot
// (assembly/prepared charts) via sqlc.
package monitorrepo

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	sqlc "bakery/internal/outbound/db/sqlc"
	"bakery/internal/pkg/enum"
	monitoringdomain "bakery/internal/services/monitor/domain"
	monitoruc "bakery/internal/services/monitor/usecase/monitor"
	orderdomain "bakery/internal/services/order/domain"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"
)

type MonitorRepository struct {
	queries *sqlc.Queries
}

var _ monitoruc.Repository = (*MonitorRepository)(nil)

func New(queries *sqlc.Queries) *MonitorRepository {
	return &MonitorRepository{queries: queries}
}

func (r *MonitorRepository) ResolveIngredient(ctx context.Context, code string) (monitoruc.Ingredient, error) {
	code = strings.TrimSpace(code)
	product, err := r.queries.GetIikoProductByCode(ctx, code)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return monitoruc.Ingredient{}, fmt.Errorf("ingredient not found by code %s", code)
		}
		return monitoruc.Ingredient{}, fmt.Errorf("get ingredient by code %s: %w", code, err)
	}
	unit := strings.TrimSpace(product.MeasureUnit)
	if unit == "" && product.Type != nil && enum.IsIikoProductType(*product.Type, enum.IikoProductTypePrepared) {
		unit = "кг"
	}
	return monitoruc.Ingredient{
		ProductID: product.ID,
		Code:      product.Code,
		Name:      product.Name,
		Unit:      unit,
	}, nil
}

func (r *MonitorRepository) LoadOrderGraph(ctx context.Context, order orderdomain.Order) (monitoruc.OrderGraph, error) {
	orderDateParam := pgDate(monitorOrderDate(order))
	result := monitoruc.OrderGraph{
		Graph: monitoringdomain.ProductGraph{},
		Items: make([]monitoruc.OrderGraphItem, 0, len(order.Items)),
	}
	productsByCode := make(map[string]sqlc.GetIikoProductByCodeRow, len(order.Items))
	for _, item := range order.Items {
		code := strings.TrimSpace(item.Code)
		product, ok := productsByCode[code]
		if !ok {
			var err error
			product, err = r.queries.GetIikoProductByCode(ctx, code)
			if err != nil {
				if errors.Is(err, pgx.ErrNoRows) {
					continue
				}
				return result, fmt.Errorf("get product by code %s: %w", item.Code, err)
			}
			productsByCode[code] = product
		}
		if err := r.loadGraph(ctx, result.Graph, product.ID, orderDateParam, make(map[string]bool, monitoringdomain.DefaultMaxDepth)); err != nil {
			return result, fmt.Errorf("load monitor graph for product %s: %w", item.Code, err)
		}
		result.Items = append(result.Items, monitoruc.OrderGraphItem{Item: item, ProductID: product.ID})
	}
	return result, nil
}

func (r *MonitorRepository) loadGraph(ctx context.Context, graph monitoringdomain.ProductGraph, productID string, orderDate pgtype.Date, path map[string]bool) error {
	if productID == "" {
		return nil
	}
	if path[productID] {
		return fmt.Errorf("monitor graph cycle detected at product %s", productID)
	}
	if _, ok := graph[productID]; ok {
		return nil
	}
	if len(path) >= monitoringdomain.DefaultMaxDepth {
		return fmt.Errorf("monitor graph max depth exceeded at product %s", productID)
	}

	assembly, err := r.queries.GetActiveAssemblyChartByProductID(ctx, sqlc.GetActiveAssemblyChartByProductIDParams{
		AssembledProductID: productID,
		OrderDate:          orderDate,
	})
	if err == nil {
		items, err := r.queries.ListAssemblyChartItemsByChartID(ctx, assembly.ID)
		if err != nil {
			return fmt.Errorf("list assembly chart items %s: %w", assembly.ID, err)
		}
		recipeItems := make([]monitoringdomain.RecipeItem, 0, len(items))
		for _, item := range items {
			recipeItems = append(recipeItems, monitoringdomain.RecipeItem{
				ProductID: item.ProductID,
				Amount:    item.AmountIn,
				Code:      item.ProductCode,
				Name:      item.ProductName,
				Unit:      item.MeasureUnit,
			})
		}
		graph[productID] = monitoringdomain.ProductRecipe{
			Assembly: &monitoringdomain.AssemblyRecipe{AssembledAmount: assembly.AssembledAmount, Items: recipeItems},
		}
		path[productID] = true
		defer delete(path, productID)
		for _, item := range items {
			if err := r.loadGraph(ctx, graph, item.ProductID, orderDate, path); err != nil {
				return err
			}
		}
		return nil
	}
	if !errors.Is(err, pgx.ErrNoRows) {
		return fmt.Errorf("get active assembly chart: %w", err)
	}

	prepared, err := r.queries.GetActivePreparedChartFullByProductID(ctx, sqlc.GetActivePreparedChartFullByProductIDParams{
		AssembledProductID: productID,
		OrderDate:          orderDate,
	})
	if errors.Is(err, pgx.ErrNoRows) {
		graph[productID] = monitoringdomain.ProductRecipe{}
		return nil
	}
	if err != nil {
		return fmt.Errorf("get active prepared chart: %w", err)
	}

	items, err := r.queries.ListPreparedChartItemsByChartID(ctx, prepared.ID)
	if err != nil {
		return fmt.Errorf("list prepared chart items %s: %w", prepared.ID, err)
	}
	recipeItems := make([]monitoringdomain.RecipeItem, 0, len(items))
	for _, item := range items {
		recipeItems = append(recipeItems, monitoringdomain.RecipeItem{
			ProductID: item.ProductID,
			Amount:    item.Amount,
			Code:      item.ProductCode,
			Name:      item.ProductName,
			Unit:      item.MeasureUnit,
		})
	}
	graph[productID] = monitoringdomain.ProductRecipe{Prepared: &monitoringdomain.PreparedRecipe{Items: recipeItems}}
	path[productID] = true
	defer delete(path, productID)
	for _, item := range items {
		if err := r.loadGraph(ctx, graph, item.ProductID, orderDate, path); err != nil {
			return err
		}
	}
	return nil
}

func monitorOrderDate(order orderdomain.Order) time.Time {
	orderDate := order.CreatedAt
	if !order.FulfillmentDate.IsZero() {
