		Amount:              item.Amount,
		RawJson:             emptyJSON,
	}); err != nil {
		return fmt.Errorf("insert prepared chart item %s: %w", item.ID, err)
	}
	return nil
}

func encodeJSON(value any) string {
	if value == nil {
		return nullJSON
	}
	data, err := json.Marshal(value)
	if err != nil {
		return emptyJSON
	}
	return string(data)
}


